\protect\hypertarget{lem-signal}{}\label{lem-signal}

Along the curve of Proposition~\ref{prp-curve},
\begin{equation}\phantomsection\label{eq-factorisation}{
  E\{g_Z(\theta(s))\}=\rho\,\varphi(s)
}\end{equation} for a function \(\varphi\) not depending on \(\rho\).

\protect\hypertarget{def-overlap}{}\label{def-overlap}

\(0<\pi_0(Y,X)<1\) almost surely; the response rate
\(E(\pi_0)=\operatorname{pr}(R=1)\) is then interior.

\protect\hypertarget{def-mgf}{}\label{def-mgf}

\(E(\pi_0e^{-w})<\infty\) and \(E(\pi_0e^{-2w})<\infty\) at every
\(\gamma\) on the portion of the curve of Proposition~\ref{prp-curve}
that is scanned.

\protect\hypertarget{thm-decomposition}{}\label{thm-decomposition}

Under Conditions \ref{def-overlap} and \ref{def-mgf} and the
normalization of Lemma~\ref{lem-intercept},
\begin{equation}\phantomsection\label{eq-decomposition}{
  E\!\left(\frac{R}{\pi_\gamma^{2}}\right)
  = E(\pi_0)+2\operatorname{pr}(R=0)+\operatorname{pr}(R=0)^{2}\,\Lambda(\gamma),
  \qquad
  \Lambda(\gamma):=\frac{E(\pi_0e^{-2w})}{\{E(\pi_0e^{-w})\}^{2}} .
}\end{equation}

\protect\hypertarget{cor-ess}{}\label{cor-ess}

Let \(\omega_i=R_i/\pi_\gamma(Y_i,X_i)\) and let
\(\widehat{\mathrm{ESS}}=(\sum_i\omega_i)^{2}/\sum_i\omega_i^{2}\) be
the effective sample size of \citet[Sec. 11.7B]{Kish1965}. Under
Lemma~\ref{lem-intercept}
\(\widehat{\mathrm{ESS}}/n\to_p1/E(R/\pi_\gamma^{2})\), and by
Theorem~\ref{thm-decomposition} the limit is \(\mathrm{ESS}(\gamma)/n\)
with \begin{equation}\phantomsection\label{eq-ess}{
  \mathrm{ESS}(\gamma) \;=\; \frac{n}{E(\pi_0)+2\operatorname{pr}(R=0)+\operatorname{pr}(R=0)^{2}\Lambda(\gamma)} .
}\end{equation} The right-hand side defines \(\mathrm{ESS}(\gamma)\);
the content of the corollary is that the sample quantity converges to
it.

\protect\hypertarget{cor-ess-bound}{}\label{cor-ess-bound}

\(\mathrm{ESS}\le n\operatorname{pr}(R=1)\), with equality exactly when
\(w\) is degenerate.

\protect\hypertarget{thm-integral}{}\label{thm-integral}

Let \(K\) be finite on an open interval containing \([0,2T]\) and set
\(\Lambda(T)=E(e^{2TW})/\{E(e^{TW})\}^{2}\). Then
\begin{equation}\phantomsection\label{eq-integral}{
  \log\Lambda(T)=\int_0^T (T-s)\left\{4\operatorname{var}_{2s}(W)-2\operatorname{var}_s(W)\right\}ds .
}\end{equation}

\protect\hypertarget{cor-sandwich}{}\label{cor-sandwich}

If \(v_-\le\operatorname{var}_s(W)\le v_+\) for all \(s\in[0,2T]\), then
\((2v_--v_+)T^{2}\le\log\Lambda(T)\le(2v_+-v_-)T^{2}\).

\protect\hypertarget{prp-dichotomy}{}\label{prp-dichotomy}

Move along the identified curve, so that \(|\gamma_Y|\to\infty\) while
\(\gamma_X(s)\) remains bounded.

\emph{(i)} If \(Y\) is binary with \(\operatorname{pr}(Y=1)\in(0,1)\),
then \begin{equation}\phantomsection\label{eq-binary-limit}{
  \Lambda(\gamma)\longrightarrow\frac{A_2}{A_1^{2}},
  \qquad A_k:=E\{\pi_0 e^{-k\gamma_X^{\mathrm{T}}X}\mathbb 1(Y=1)\} ,
}\end{equation} a finite constant: the tilt cannot explode, however
strong the assumed departure from ignorability.

\emph{(ii)} If \(Y\) has Gaussian-like tails,
\(\Lambda(\gamma)\to\infty\), at a rate quadratic in \(\gamma_Y\);
Corollary~\ref{cor-sandwich} brackets the constant.

\protect\hypertarget{lem-varprop}{}\label{lem-varprop}

Let \(Y\mid X,Z\sim N(\mu(X,Z),\varsigma^{2})\) and let
\(\pi(y)=\operatorname{expit}(\gamma_0+\gamma_X^{\mathrm{T}}x+\gamma_Y y)\).
Then \begin{equation}\phantomsection\label{eq-varprop}{
  \frac{\varsigma^{2}}{1+\gamma_Y^{2}\varsigma^{2}/4}\;\le\;\operatorname{var}(Y\mid R=1,X,Z)\;\le\;\varsigma^{2},
}\end{equation} with the upper bound strict whenever \(\gamma_Y\neq0\).

\protect\hypertarget{thm-reach}{}\label{thm-reach}

Let \(m>0\) be the smallest effective sample size at which the statistic
can be evaluated. Then the scan reaches
\begin{equation}\phantomsection\label{eq-reach}{
  |\gamma_Y|_{\max}
  =\left[\frac{\log(n/m)-2\log\{\operatorname{pr}(R=0)\}}{v_\infty}\right]^{1/2}\{1+o(1)\} ,
}\end{equation} which grows like \((\log n)^{1/2}\) and does not depend
on \(\rho\). Moreover \(\Lambda\) itself exceeds the largest
representable number once
\(\log\Lambda>\log(\texttt{DBL\_MAX})\doteq709.78\), so that
\(|\gamma_Y|\le\{709.78/v_\infty\}^{1/2}\) irrespective of \(n\).

\protect\hypertarget{lem-factorisation}{}\label{lem-factorisation}

\(M=\tilde MD\) with \(D=\operatorname{diag}(I,\rho I)\) and
\(\tilde M\) free of \(\rho\), the second block corresponding to the
coordinates of \(b\) involving \(Z\). Consequently
\(\Theta=D^{-1}\tilde M^{-1}r\) carries a factor \(\rho^{-1}\) on those
coordinates, while \(v\) carries a factor \(\rho\) on the same
coordinates, and \begin{equation}\phantomsection\label{eq-cancellation}{
  q^{\mathrm{T}}:=v^{\mathrm{T}}M^{-1}=\tilde v^{\mathrm{T}}\tilde M^{-1}
  \quad\text{is free of }\rho .
}\end{equation}

\protect\hypertarget{thm-orders}{}\label{thm-orders}

Under Lemma~\ref{lem-factorisation} and the regularity conditions of
Section~\ref{sec-conditions},
\begin{equation}\phantomsection\label{eq-orders}{
  \|G_\lambda(\beta_0)\|\asymp\lambda/\rho,
  \qquad
  \operatorname{sd}(\hat\beta_\lambda)\asymp n^{-1/2}/\rho,
  \qquad
  \operatorname{cond}(M)\asymp\rho^{-1} .
}\end{equation}

\protect\hypertarget{thm-if}{}\label{thm-if}

With \(\lambda_n=o(n^{-1/2})\),
\(n^{1/2}(\hat\beta_{\lambda_n}-\beta_0)\to N\{0,H^{-1}\operatorname{var}(\mathrm{IF})H^{-\mathrm{T}}\}\),
where \begin{equation}\phantomsection\label{eq-if}{
  \mathrm{IF}(O)=R\psi(\beta_0)+(1-R)\delta_0(X,Z)+R\{\psi(\beta_0)-\delta_0(X,Z)\}a(X,Y)^{\mathrm{T}}q
}\end{equation} and, by (\ref{eq-rep}),
\(H=E\{\partial\psi(\beta_0)/\partial\beta^{\mathrm{T}}\}\) is the
complete-data Jacobian.

\protect\hypertarget{thm-drifting}{}\label{thm-drifting}

Let \(\rho_n=c/n^{1/2}\) with \(c>0\) fixed, partition the sieve as
\(b=(b^{0}(X),Zk(X))\), and assume that \(A:=E(Rab^{0\mathrm{T}})\) has
full column rank, that the fourth moments of Theorem~\ref{thm-orders}
hold, and that
\(\Omega:=\operatorname{var}\{\operatorname{vec}(Ra\nu k^{\mathrm{T}})\}\)
is nonsingular on the orthogonal complement of the column space of
\(A\). Then \begin{equation}\phantomsection\label{eq-drifting}{
  \hat q:=\hat M^{-\mathrm{T}}\hat v\;\Rightarrow\;[A,\Psi]^{-\mathrm{T}}(v_0,\Phi),
  \qquad \Psi=c\tilde m+\xi,\quad \Phi=c\tilde v+\zeta,
}\end{equation} with \((\xi,\zeta)\) jointly Gaussian. The limit is
random, not constant, and depends on \(c\); consequently
\(\hat\beta-\beta_0=O_p(1)\) and is not \(o_p(1)\) at any rate.

\protect\hypertarget{lem-resolvent}{}\label{lem-resolvent}

Let \(M=\sum_k\sigma_ku_kv_k^{\mathrm{T}}\) with \(s:=\sigma_{\min}(M)\)
attained at \((u_1,v_1)\), let \(s_2\) be the next singular value, and
put \(\cos\theta:=u_1^{\mathrm{T}}v_1\), signed, and well defined
because the sign ambiguity of the singular vectors flips \(u_1\) and
\(v_1\) together. For \(\lambda<s\),
\begin{equation}\phantomsection\label{eq-resolvent}{
  (M+\lambda I)^{-1}=\frac{v_1u_1^{\mathrm{T}}}{s+\lambda\cos\theta}+E_\lambda,
  \qquad \|E_\lambda\|=O\{(s_2-\lambda)^{-1}\} .
}\end{equation}

\protect\hypertarget{prp-sdlambda}{}\label{prp-sdlambda}

Under Theorem~\ref{thm-if} and Lemma~\ref{lem-resolvent}, if
\(\|\hat M-M\|=o_p(s+\lambda\cos\theta)\) then
\begin{equation}\phantomsection\label{eq-sdlambda}{
  \operatorname{sd}(\hat\beta_\lambda)
  =\sigma_0\,\frac{s}{s+\lambda\cos\theta}\,\{1+O(\lambda/s_2)\},
  \qquad
  \sigma_0^{2}=\frac{\kappa}{n\rho^{2}} ,
}\end{equation} with \(\kappa\) free of \(\lambda\), of \(\rho\) and of
\(n\).

\protect\hypertarget{def-mom}{}\label{def-mom}

\(E\|a\|^{4}<\infty\), \(E\|b\|^{4}<\infty\),
\(E\|\psi(\beta_0)\|^{4}<\infty\) and \(E\|\delta_0\|^{4}<\infty\).
